'use strict';
/* public/js/25-people.js -- camper avatars, name/speech labels. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- people ---------- */
const CAMPER_COLORS=[0xd94f3a,0x2f7bb8,0x6b9a3a,0x8a4bb0,0xd9a21a,0x2a9a8a,0xe07ab0,0x444444];
function makePerson(o){
  const g=new T.Group();
  const suit=o.suit||0xe8742a;
  const legL=new T.Group(),legR=new T.Group(),armL=new T.Group(),armR=new T.Group();
  legL.position.set(-0.13,0.8,0);legR.position.set(0.13,0.8,0);
  for(const L of[legL,legR]){const m=box(0.19,0.8,0.21,suit);m.position.y=-0.4;L.add(m);const b=box(0.21,0.14,0.28,0x3a2a1c);b.position.set(0,-0.76,0.03);L.add(b)}
  const upper=new T.Group();upper.position.y=0.8;
  const torso=box(0.54,0.64,0.32,suit);torso.position.y=0.32;
  const collar=box(0.3,0.06,0.33,o.shirt||0xe8e0cc);collar.position.y=0.62;
  armL.position.set(-0.35,0.58,0);armR.position.set(0.35,0.58,0);
  for(const A of[armL,armR]){const m=box(0.15,0.46,0.17,suit);m.position.y=-0.2;A.add(m);const h=box(0.13,0.16,0.14,o.skin);h.position.y=-0.52;A.add(h)}
  const head=box(0.36,0.36,0.34,o.skin);head.position.y=0.86;
  const eyeL=box(0.05,0.05,0.02,0x1a1a1a),eyeR=eyeL.clone();eyeL.position.set(-0.08,0.89,0.175);eyeR.position.set(0.08,0.89,0.175);
  let hat;
  if(o.hat==='cowboy'){hat=new T.Group();const br=cyl(0.42,0.42,0.04,10,0x8a6a44);const cr=cyl(0.2,0.24,0.2,8,0x8a6a44);cr.position.y=0.12;hat.add(br,cr);hat.position.y=1.06}
  else if(o.hat==='none'){hat=new T.Group();const hair=box(0.38,0.1,0.36,0x6a2a1a);hair.position.y=1.06;hat.add(hair)}
  else{hat=new T.Group();const br=cyl(0.33,0.33,0.03,10,0xd9cfae);const cr=cyl(0.19,0.21,0.15,10,0xd9cfae);cr.position.y=0.09;const band=cyl(0.215,0.215,0.05,10,o.band||0x2f5f8a);band.position.y=0.04;hat.add(br,cr,band);hat.position.y=1.06}
  let shovel=null;
  if(o.shovel!==false){shovel=new T.Group();const hd=cyl(0.028,0.028,1.2,5,0x8a6440);hd.position.y=-0.3;const bl=box(0.24,0.3,0.035,0x7d8288);bl.position.y=-0.98;shovel.add(hd,bl);shovel.position.set(0,-0.52,0.05);shovel.rotation.x=-0.45;armR.add(shovel)}
  if(o.shades){const s=box(0.3,0.07,0.02,0x111111);s.position.set(0,0.89,0.18);upper.add(s)}
  upper.add(torso,collar,armL,armR,head,eyeL,eyeR,hat);g.add(legL,legR,upper);
  const p={g,upper,legL,legR,armL,armR,shovel,hat,ph:0,o};
  if(MODEL.ready)upgradePerson(p);else MODEL.people.push(p);   // the Blender camper replaces these boxes once it loads (below)
  return p;
}
/* one scoop: [phase, lean, twist, right arm, left arm] — drive in, lift, toss onto the pile, reset */
const DIGK=[[0,0.15,0,-0.5,-0.6],[0.3,0.55,0,-0.95,-0.8],[0.5,0.25,0.1,-1.6,-1.25],[0.72,0.08,0.7,-1.9,-1.5],[1,0.15,0,-0.5,-0.6]];
function digPose(t){for(let i=1;i<DIGK.length;i++){if(t<=DIGK[i][0]){const a=DIGK[i-1],b=DIGK[i],k=sm((t-a[0])/(b[0]-a[0]));return[lerp(a[1],b[1],k),lerp(a[2],b[2],k),lerp(a[3],b[3],k),lerp(a[4],b[4],k)]}}return DIGK[0].slice(1)}
/* Asleep in a bunk: flat on your back on the mattress, head on the pillow (pillows sit toward the bunk's -z end), arms
   at your sides, shovel put away. The body's origin is at the feet, so rotation.x = -PI/2 lays it back with the head
   toward -z. Used for you, other campers (they send anim 3 while in a room) and the D Tent crew. */
const BUNK_TOP_LO=0.56,BUNK_TOP_HI=1.72;   // mattress top above the room floor for a lower / upper bunk (20-world.js)
const SLEEP_FEET_DZ=0.98,SLEEP_BACK=0.17;  // feet this far toward +z from the bunk centre; body centre-line above the mattress
function sleepPose(p,bk){
  p.g.position.set(bk.x,TENT_FLOOR_Y+(bk.high?BUNK_TOP_HI:BUNK_TOP_LO)+SLEEP_BACK,bk.z+SLEEP_FEET_DZ);
  p.g.rotation.set(-Math.PI/2,0,0);
  p.upper.rotation.set(0,0,0);p.armL.rotation.set(0,0,0.08);p.armR.rotation.set(0,0,-0.08);p.legL.rotation.set(0,0,0);p.legR.rotation.set(0,0,0);
  if(p.shovel)p.shovel.visible=false;
  if(p.shovelMeshes)for(const n of p.shovelMeshes)n.visible=false;
}
function animPerson(p,mode,dt,digPhase,speed){
  if(p.model){animModel(p,mode,dt,digPhase,speed);return}
  if(p.emote)emotePose(p,dt||0.016);   // box people: no pose, but the emote still times out (and a twerk still ends in a fart)
  if(p.shovel)p.shovel.visible=!p.stowed;   // back in hand when you're up (sleepPose hides it), unless it's on a rack (p.stowed)
  if(mode===3){p.g.rotation.x=lerp(p.g.rotation.x,-Math.PI/2,Math.min(1,dt*8));return}
  p.g.rotation.x=lerp(p.g.rotation.x,0,Math.min(1,dt*8));
  const k=Math.min(1,dt*10);
  if(mode===2){
    const[lean,twist,ar,al]=digPose(clamp(digPhase||0,0,1));
    p.upper.rotation.x=lean;p.upper.rotation.y=twist;p.armR.rotation.x=ar;p.armL.rotation.x=al;p.armL.rotation.z=0;
    p.legL.rotation.x=-lean*0.5;p.legR.rotation.x=lean*0.3;return;
  }
  p.upper.rotation.y=lerp(p.upper.rotation.y,0,k);p.armL.rotation.z=lerp(p.armL.rotation.z,0,k);
  if(mode===1||mode===4){
    p.upper.rotation.x=lerp(p.upper.rotation.x,mode===4?0.18:0.05,k);
    p.ph+=dt*(mode===4?14:9)*(speed||1);const s=Math.sin(p.ph);
    p.legL.rotation.x=s*0.7;p.legR.rotation.x=-s*0.7;p.armL.rotation.x=-s*0.6;p.armR.rotation.x=s*0.6;
  }else if(mode===5){ /* drink from the canteen */
    p.upper.rotation.x=lerp(p.upper.rotation.x,-0.3,k);p.armR.rotation.x=lerp(p.armR.rotation.x,-2.6,k);p.armL.rotation.x=lerp(p.armL.rotation.x,0,k);
    p.legL.rotation.x*=0.8;p.legR.rotation.x*=0.8;
  }else if(mode===6){ /* wipe the sweat off */
    p.upper.rotation.x=lerp(p.upper.rotation.x,-0.1,k);p.armL.rotation.x=lerp(p.armL.rotation.x,-2.7,k);p.armL.rotation.z=Math.sin(performance.now()/140)*0.35;p.armR.rotation.x=lerp(p.armR.rotation.x,-0.3,k);
  }else{
    p.upper.rotation.x=lerp(p.upper.rotation.x,0,k);
    p.legL.rotation.x*=0.8;p.legR.rotation.x*=0.8;p.armL.rotation.x=lerp(p.armL.rotation.x,0,dt*6);p.armR.rotation.x=lerp(p.armR.rotation.x,-0.1,dt*6);
  }
}

/* ---------- the Blender camper (models/camper.glb, built by blender/cgl_rig.py) ----------
   The box people above are the fallback until the model arrives (or if it can't load). Every person from
   makePerson is upgraded in place, keeping the same p.g group, so movement/labels/network code is unchanged. */
const MODEL={ready:false,scene:null,clips:[],people:[]};
const MODEL_SCALE=0.68;
const SKIN_TONES=[0xf3d3b5,0xe8bb92,0xd6a077,0xc68a5e,0xa56b43,0x7f5134,0x5e3a25,0x43291b];
const HAIR_COLORS=[0x1f1511,0x3b2618,0x6a4426,0xb88a4a,0x8a3a1c];
/* w/d = torso width/depth, h = overall height, limb = arm/leg thickness */
const BODY_TYPES={average:{w:1,d:1,h:1,limb:1},slim:{w:0.86,d:0.9,h:1.03,limb:0.88},stocky:{w:1.17,d:1.14,h:0.97,limb:1.12},tall:{w:0.95,d:0.97,h:1.09,limb:0.96},short:{w:1.06,d:1.05,h:0.9,limb:1.04}};
const BODY_KEYS=Object.keys(BODY_TYPES);
/* cowboy hats are staff-only (Mr. Sir + the Warden) */
const HAT_ROLL=['bucket','bucket','bucket','desert','desert','desert','none','none'];
const HAT_NODE={bucket:'Bucket',desert:'DesertCap',cowboy:'Cowboy'};
/* animPerson modes -> clips. 0-6 are the game's existing modes; 7 jump, 8 dance, 9 wave, 10 sit, 11 sit on an edge are local-only */
const MODE_CLIP=['Idle','Walk','Dig','KO','Run','Drink','WipeSweat','Jump','Dance','Wave','Sit','SitEdge'];   // 10: sitting (86-sit.js), 11: on an edge, legs dangling (the pickup's tailgate)
const CLIP_ONCE={KO:1,Jump:1,Drink:1,WipeSweat:1,Wave:1};
function strHash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return h>>>0}
/* same name + color -> same camper on every client */
function playerLook(name,ci){
  const h=strHash(String(name).toLowerCase()+'#'+ci);
  return{skin:SKIN_TONES[h%SKIN_TONES.length],band:CAMPER_COLORS[ci],hat:HAT_ROLL[(h>>>4)%HAT_ROLL.length],
    body:BODY_KEYS[(h>>>8)%BODY_KEYS.length],hair:HAIR_COLORS[(h>>>12)%HAIR_COLORS.length]};
}
/* the sharpened spade (the store's, for you or a crew member): its steel goes from the camp's dull blue-grey to a dark,
   blued gunmetal, so you can tell at a glance who's got one. The blade, ridge and socket share the camper's
   CGL_SteelBlue material (art: blender/camper); each camper with one gets their own darker copy of it. */
const SPADE_SHARP={color:0x2b3036,metal:0.85,rough:0.28};
function spadeLook(p,sharp){
  if(!p)return;sharp=!!sharp;const vm=p===me&&typeof VM_SHOVEL!=='undefined'?VM_SHOVEL:[],key=(p.model?'m':'b')+sharp+vm.length;if(p.spadeLook===key)return;p.spadeLook=key;
  for(const n of[...(p.shovelMeshes||[]),...vm]){const m=n.userData.steel0||(n.material&&n.material.name==='CGL_SteelBlue'?n.material:null);if(!m)continue;
    n.userData.steel0=m;
    if(sharp){if(!n.userData.steelSharp){const c=m.clone();c.color.setHex(SPADE_SHARP.color);if('metalness'in c)c.metalness=SPADE_SHARP.metal;if('roughness'in c)c.roughness=SPADE_SHARP.rough;n.userData.steelSharp=c}n.material=n.userData.steelSharp}
    else n.material=m}
}
/* the long-handled shovel (the store's): the camper model carries a second, longer handle with a steel collar and a red
   cap (blender/cgl_rig.py long_handle: CGLCamper_R_Shovel{Shaft,Collar,Cap}Long) on the same blade. A camper who's
   bought one (p.longShovel: you from S.up.long, friends from 'pos' lg) shows it in place of the camp handle. */
function shovelPart(n){if(/Long$/.test(n.name))n.userData.longPart=true;else if(/_R_Shovel(Shaft|Cap)$/.test(n.name))n.userData.campPart=true}
function shovelShows(p,n){if(p.noShovel)return false;   // bare hands: no shovel yet (S.up.shovel; friends' 'pos' sh)
  return n.userData.longPart?!!p.longShovel:n.userData.campPart?!p.longShovel:true}
function upgradePerson(p){
  if(p.model||!MODEL.ready)return;
  const o=p.o||{},bt=BODY_TYPES[o.body]||BODY_TYPES.average;
  const m=T.SkeletonUtils?T.SkeletonUtils.clone(MODEL.scene):MODEL.scene.clone(true);
  m.scale.setScalar(MODEL_SCALE*bt.h);
  const hat=o.hat==='none'?null:HAT_NODE[o.hat]||'Bucket';
  const tint={CGL_Skin:o.skin,CGL_HatBand:o.band,CGL_Hair:o.hair!=null?o.hair:HAIR_COLORS[0],CGL_Jumpsuit:o.suit};
  if(o.band!=null)tint.CGL_Patch=new T.Color(o.band).lerp(new T.Color(0xffffff),0.55).getHex();
  const mats={},torso=[];
  m.traverse(n=>{
    if(!n.isMesh)return;
    n.castShadow=true;n.receiveShadow=true;
    const nm=n.name;
    if(/_(Bucket|Cowboy|DesertCap)_/.test(nm))n.visible=!!hat&&nm.includes('_'+hat+'_');
    else if(nm.includes('_Hair_'))n.visible=!hat;
    else if(nm.includes('_Shades_'))n.visible=!!o.shades;
    else if(nm.includes('_R_Shovel')){shovelPart(n);n.visible=o.shovel!==false&&shovelShows(p,n);(p.shovelMeshes=p.shovelMeshes||[]).push(n)}
    const mn=n.material&&n.material.name;
    // one tinted copy per material AND per kind of mesh: the rigid hands/sneakers share names with the skinned sleeves
    // and trousers, and a skinned mesh given a rigid mesh's material (skinning off) draws its shadow in the bind pose
    // (and three.js warns about it every frame)
    if(mn&&tint[mn]!=null){const key=mn+(n.isSkinnedMesh?'#skin':'');if(!mats[key]){mats[key]=n.material.clone();mats[key].color.setHex(tint[mn]);mats[key].skinning=!!n.isSkinnedMesh}n.material=mats[key]}
    if(n.isSkinnedMesh&&n.material&&!n.material.skinning){n.material=n.material.clone();n.material.skinning=true}
    if(/_(Torso|Zipper|Patch|Neck)$/.test(nm))torso.push(n);
    if(/_[LR]_(Sleeve|Elbow|Forearm|Leg)$/.test(nm)){
      // A skinned limb's vertices are sized in bind space; scaling its object would move it off the joint.
      if(n.isSkinnedMesh&&bt.limb!==1){
        const bn=(nm.endsWith('_Leg')?'leg':'arm')+(nm.includes('_L_')?'L':'R');
        const i=n.skeleton.bones.findIndex(b=>b.name===bn),inv=n.skeleton.boneInverses[i];
        const radial=n.bindMatrixInverse.clone().multiply(inv.clone().invert())
          .multiply(new T.Matrix4().makeScale(bt.limb,1,bt.limb)).multiply(inv).multiply(n.bindMatrix);
        n.geometry=n.geometry.clone().applyMatrix4(radial);
      }
      else if(!n.isSkinnedMesh)n.scale.set(bt.limb,1,bt.limb);
    }
  });
  /* body width: scale the torso pieces in spine space, then push shoulders/hips out to match (after each mixer update) */
  const spine=m.getObjectByName('spine');
  if(spine&&(bt.w!==1||bt.d!==1)){const wg=new T.Group();spine.add(wg);for(const n of torso)wg.add(n);wg.scale.set(bt.w,1,bt.d)}
  /* [bone, x offset, rest position]: the GLB drops constant position tracks, so restore the rest spot before
     every mixer update and add the offset after it (otherwise the offset piles up frame after frame) */
  const W=bt.w-1;p.adj=[];
  for(const[bn,dx]of[['armL',-0.355*W],['armR',0.355*W],['legL',-0.15*W],['legR',0.15*W]]){const b=m.getObjectByName(bn);if(b)p.adj.push([b,dx,b.position.clone()])}
  p.mixer=new T.AnimationMixer(m);p.acts={};
  for(const c of MODEL.clips){const a=p.mixer.clipAction(c);if(CLIP_ONCE[c.name]){a.setLoop(T.LoopOnce,1);a.clampWhenFinished=true}p.acts[c.name]=a}
  for(const c of p.g.children)c.visible=false;   /* hide the box fallback */
  p.g.rotation.x=0;p.g.add(m);p.model=m;p.cur=null;p.lastT=performance.now();
  setClip(p,'Idle',0);stepMixer(p,0);
  if(p.hatT)modelHat(p,p.hatT);
}
/* level-reward hats on the model: recolor the camper's own hat (cowboy hats stay staff-only, so hair gets a
   bucket hat), and the top tier puts a pig on their head */
const TIER_HAT=[0,0xd9c27a,0x222222,0xd4af37];
function modelHat(p,t){
  const m=p.model;if(!m||!t)return;
  if(p.pig){p.pig.parent.remove(p.pig);p.pig=null}
  const own=p.o&&p.o.hat==='desert'?'DesertCap':'Bucket';
  m.traverse(n=>{
    if(!n.isMesh)return;const nm=n.name;
    if(/_(Bucket|Cowboy|DesertCap)_/.test(nm))n.visible=t<4&&nm.includes('_'+own+'_');
    else if(nm.includes('_Hair_'))n.visible=t===4;
    if(t<4&&nm.includes('_'+own+'_')&&!/HatBand$/.test(nm)){n.material=n.material.clone();n.material.color.setHex(TIER_HAT[t])}
  });
  if(t===4){
    const head=m.getObjectByName('head');if(!head)return;
    const g=new T.Group(),b=box(0.3,0.22,0.42,0xf2a0b0),hd=box(0.2,0.18,0.14,0xf2a0b0),sn=box(0.09,0.06,0.04,0xd97a8e);
    b.position.y=0.12;hd.position.set(0,0.16,0.26);sn.position.set(0,0.14,0.34);g.add(b,hd,sn);
    g.scale.setScalar(1/MODEL_SCALE);g.position.set(0,0.68,0);head.add(g);p.pig=g;
  }
}
function stepMixer(p,dt){
  if(p.poseRest)for(const[b,q,pos]of p.poseRest){b.quaternion.copy(q);b.position.copy(pos)}   // emote offsets (73-emotes.js) from last frame
  for(const[b,,rest]of p.adj)b.position.copy(rest);
  p.mixer.update(dt);
  for(const[b,dx]of p.adj)b.position.x+=dx;
}
function setClip(p,name,fade){
  if(p.cur===name||!p.acts[name])return;
  const a=p.acts[name],f=fade==null?0.18:fade;
  a.reset();a.timeScale=1;a.setEffectiveWeight(1);a.fadeIn(f).play();
  if(p.cur&&p.acts[p.cur])p.acts[p.cur].fadeOut(f);
  p.cur=name;
}
function animModel(p,mode,dt,digPhase,speed){
  const now=performance.now();if(dt==null)dt=Math.min(0.05,(now-p.lastT)/1000);p.lastT=now;
  p.g.rotation.x=0;
  if(p.shovelMeshes)for(const n of p.shovelMeshes)n.visible=(!p.o||p.o.shovel!==false)&&!p.stowed&&shovelShows(p,n);   // back in hand once you're up (sleepPose hides it), unless it's on a rack (p.stowed)
  if(p.waveT>0){p.waveT-=dt;if(mode===0)mode=9}
  const name=MODE_CLIP[mode]||'Idle';
  setClip(p,name);
  const a=p.acts[name];
  if(a&&name==='Dig'){a.timeScale=0;a.time=clamp(digPhase||0,0,0.999)*a.getClip().duration}   /* scoops stay in sync with the game's dig timer */
  else if(a&&(name==='Walk'||name==='Run'))a.timeScale=speed||1;
  stepMixer(p,dt);
  if(p.emote)emotePose(p,dt);   // twerk / sing, layered on top of the clip (73-emotes.js)
  if(p.held||p.heldW)heldPose(p,dt);   // walkie-talkie / tonic / first-aid kit in the left hand (86-walkie.js)
}
function loadCamperModel(){
  if(!T.GLTFLoader||!/^https?:$/.test(location.protocol))return;
  new T.GLTFLoader().load('models/camper.glb?v=7',g=>{
    MODEL.scene=g.scene;
    /* the renderer draws hex colors as-is (no sRGB output), but glTF colors arrive linear: convert them back
       so the model's orange matches the rest of the camp */
    const seen=new Set();
    g.scene.traverse(n=>{if(n.isMesh&&n.material&&!seen.has(n.material)){seen.add(n.material);n.material.color.convertLinearToSRGB()}});
    MODEL.clips=g.animations.map(c=>{c.tracks=c.tracks.filter(t=>!t.name.endsWith('.scale'));return c});
    MODEL.ready=true;
    for(const p of MODEL.people)upgradePerson(p);
    MODEL.people.length=0;
  },undefined,e=>console.warn('Camper model failed to load, keeping the box people.',e));
}
loadCamperModel();

/* ---------- labels (names + speech bubbles) ---------- */
const labelLayer=$('#labels');const labeled=[];
function makeLabel(obj,name,cls,h){
  const el=document.createElement('div');el.className='tag '+(cls||'');
  const b=document.createElement('div');b.className='bubble';const n=document.createElement('span');n.className='nm';n.textContent=name;
  el.append(b,n);labelLayer.appendChild(el);
  const L={obj,el,b,n,h:h||2.25,sayUntil:0};labeled.push(L);return L;
}
function say(L,text,secs){L.b.textContent=text;L.sayUntil=performance.now()+(secs||4200)}
const projV=new T.Vector3();
function updateLabels(now){
  const w=innerWidth,h=innerHeight;
  for(const L of labeled){
    if(!L.obj.visible&&L.obj.parent){L.el.style.display='none';continue}
    // inside a tent you only see tags from inside (the rooms are underground), and outside only tags from outside
    if((L.obj.position.y<TENT_FLOOR_Y+2)!==inTent()){L.el.style.display='none';continue}
    if(L.sayUntil&&now>L.sayUntil){L.b.textContent='';L.sayUntil=0}
    projV.set(L.obj.position.x,L.obj.position.y+L.h,L.obj.position.z);
    const dist=projV.distanceTo(camera.position);
    projV.project(camera);
    if(projV.z>1||dist>(L.b.textContent?80:38)||Math.abs(projV.x)>1.2||Math.abs(projV.y)>1.2){L.el.style.display='none';continue}
    L.el.style.display='';L.el.style.transform=`translate(-50%,-100%) translate(${((projV.x+1)/2*w).toFixed(1)}px,${((1-projV.y)/2*h).toFixed(1)}px)`;
  }
}
